def split_csv(line):
    fields = []
    i = 0

    while i <= len(line):
        # If we're at the end of the line, we've successfully parsed a field
        if i == len(line):
            fields.append('')
            break

        # Check if this is a quoted field
        if line[i] == '"':
            # Parse quoted field
            i += 1
            field = ''
            while i < len(line):
                if line[i] == '"':
                    # Found a quote - check if it's doubled or the end quote
                    if i + 1 < len(line) and line[i + 1] == '"':
                        # Doubled quote - add single quote to field
                        field += '"'
                        i += 2
                    else:
                        # End quote - check what follows
                        i += 1
                        if i == len(line):
                            # End of line - valid
                            fields.append(field)
                            return fields
                        elif line[i] == ',':
                            # Comma follows - valid
                            fields.append(field)
                            i += 1
                            if i == len(line):
                                # Trailing comma means empty field follows
                                fields.append('')
                                return fields
                            # Continue to parse next field
                            break
                        else:
                            # Something else follows the closing quote
                            return None
                else:
                    field += line[i]
                    i += 1

            # If we exited the while loop without break, the quote was unterminated
            if i >= len(line) and fields and field is not None:
                # We may have exited because we ran out of characters
                if not (i > len(line) or (i == len(line) and line[i - 1] == '"')):
                    return None
            # Continue to next iteration of outer loop
        else:
            # Parse unquoted field
            field = ''
            while i < len(line) and line[i] != ',':
                if line[i] == '"':
                    # Unquoted field contains a quote - malformed
                    return None
                field += line[i]
                i += 1

            fields.append(field)

            if i == len(line):
                # End of line - we're done
                return fields
            elif line[i] == ',':
                # Move past comma
                i += 1
                if i == len(line):
                    # Trailing comma means empty field follows
                    fields.append('')
                    return fields

    return fields

